import json, urllib.request, time
cfg=json.load(open('/Users/mac/Desktop/CHcode/.claude/database/dc-platform.json'))
base=cfg['base_url'].rstrip(); token=cfg['token']
H={'Authorization': f'Bearer {token}','Content-Type':'application/json'}

def api(method, path, body=None, timeout=180):
    data=None if body is None else json.dumps(body).encode()
    req=urllib.request.Request(base+path, data=data, headers=H, method=method)
    try:
        with urllib.request.urlopen(req, timeout=timeout) as r:
            raw=r.read(); return json.loads(raw) if raw else {}
    except urllib.error.HTTPError as e:
        print('HTTP', e.code, e.read().decode()[:1200]); raise

def follow(run_id, env, label):
    for i in range(80):
        time.sleep(4)
        g=api('GET', f'/api/v1/runner/runs/{run_id}?env={env}')
        print(label, g.get('state'), g.get('rc'))
        if g.get('state') in ('success','failed','error'):
            print(json.dumps(g.get('result') or g, ensure_ascii=False)[:2000])
            return g
    return g

